// End-to-end lock: the ground-state energies recorded in the frozen model
// fixtures of src/alps/models/tests (generated by the alpsx Python kit) are
// reproduced by prepare_product + eigenstates, densely in the full space and
// by Lanczos in a symmetry sector where the space is large enough.

#include <alps/ed/product_problem.hpp>
#include <alps/models/builtin.hpp>

#include <gtest/gtest.h>

#include <algorithm>
#include <cmath>
#include <fstream>
#include <functional>
#include <limits>
#include <map>
#include <sstream>
#include <string>
#include <vector>

namespace lat = alps::lattice;
namespace mdl = alps::models;

namespace {

// Ground state of the L=16 periodic Heisenberg chain in Sz=0 (dimension
// 12870), measured once with alps::ed::dense_eigensystem on the same
// sector (131 s; the Lanczos path below agrees to 2e-15 in 0.1 s). The
// Bethe-ansatz finite-size value is -7.1422963606.
constexpr double kHeisenberg16E0 = -7.142296360616779;

lat::Lattice kondo_geometry(int L) {
    lat::UnitCell uc(1);
    uc.add_vertex({0.0}, 0);
    uc.add_vertex({0.5}, 1);
    uc.add_edge(0, 0, 0, {}, {1});
    uc.add_edge(0, 1, 1);
    return uc.tile({L});
}

std::map<std::string, std::function<mdl::Hamiltonian()>> const& registry() {
    static std::map<std::string, std::function<mdl::Hamiltonian()>> const r = {
        {"heisenberg_chain_L6",  [] { return mdl::heisenberg(lat::chain(6), 1.0); }},
        {"heisenberg_ladder_L3", [] { return mdl::heisenberg(lat::ladder(3), 1.0); }},
        {"ising_chain_L5_h",     [] { return mdl::ising(lat::chain(5), 1.0, 0.3); }},
        {"xxz_chain_L6",         [] { return mdl::xxz(lat::chain(6), 1.0, 0.5); }},
        {"tfi_chain_L6",
         [] { return mdl::transverse_field_ising(lat::chain(6), 1.0, 0.7); }},
        {"heisenberg_d_chain_L4_S1",
         [] { return mdl::heisenberg_d(lat::chain(4), 1.0, 0.2, 0.0, 1.0); }},
        {"biquadratic_chain_L4_S1",
         [] { return mdl::biquadratic(lat::chain(4), 1.0, 0.3, 1.0); }},
        {"j1j2_mg_L6",           [] { return mdl::j1j2(lat::nnn_chain(6), 1.0, 0.5); }},
        {"hubbard_chain_L4",     [] { return mdl::hubbard(lat::chain(4), 1.0, 2.0, 0.3); }},
        {"spinless_chain_L6",
         [] { return mdl::spinless_fermion_model(lat::chain(6), 1.0, 0.2, 0.5); }},
        {"tj_chain_L4",          [] { return mdl::t_j(lat::chain(4), 1.0, 0.4); }},
        {"kondo_L3",             [] { return mdl::kondo_lattice(kondo_geometry(3), 1.0, 1.0, 0.1); }},
        {"hardcore_boson_chain_L6",
         [] { return mdl::hardcore_boson_model(lat::chain(6), 1.0, 0.1, 0.4); }},
        {"bose_hubbard_chain_L4",
         [] { return mdl::bose_hubbard(lat::chain(4), 1.0, 1.5, 0.7, 0.0, 2); }},
    };
    return r;
}

double fixture_e0(std::string const& name) {
    std::ifstream in(std::string(ALPS_MODELS_FIXTURES) + "/models/" + name + ".fixture");
    if (!in) throw std::runtime_error("cannot open fixture " + name);
    std::string line;
    while (std::getline(in, line)) {
        std::istringstream ss(line);
        std::string tag;
        double value;
        if (ss >> tag >> value && tag == "e0") return value;
    }
    throw std::runtime_error("fixture " + name + " records no e0");
}

alps::ed::EigenstateOptions options(int count, alps::ed::EigenstateMethod method) {
    alps::ed::EigenstateOptions o;
    o.count = count;
    o.method = method;
    return o;
}

alps::ed::ProductOptions sector(std::map<std::string, double> charges) {
    alps::ed::ProductOptions o;
    o.sector = std::move(charges);
    return o;
}

} // namespace

TEST(ModelsFixtureE0, DenseFullSpaceReproducesEveryFixture) {
    int cases = 0;
    for (auto const& [name, builder] : registry()) {
        SCOPED_TRACE(name);
        auto const problem = alps::ed::prepare_product(builder());
        auto const result = problem.eigenstates(options(1, alps::ed::EigenstateMethod::dense));
        ASSERT_EQ(result.eigenvalues.size(), 1);
        EXPECT_NEAR(result.eigenvalues[0], fixture_e0(name), 1e-8);
        ++cases;
    }
    EXPECT_EQ(cases, 14);
}

TEST(ModelsFixtureE0, SectorsPartitionTheSpectrum) {
    // The lowest sector ground state over every charge sector is the global
    // one recorded in the fixture; empty sectors return no eigenvalues. The
    // even antiferromagnetic chains hold their singlet ground state in Sz=0.
    struct Case {
        char const* name;
        std::vector<std::map<std::string, double>> sectors;
        std::map<std::string, double> ground;
    };
    std::vector<Case> cases;
    auto spin_sectors = [](int L) {
        std::vector<std::map<std::string, double>> out;
        for (int twice = -L; twice <= L; twice += 2) out.push_back({{"Sz", twice / 2.}});
        return out;
    };
    cases.push_back({"heisenberg_chain_L6", spin_sectors(6), {{"Sz", 0.}}});
    cases.push_back({"xxz_chain_L6", spin_sectors(6), {{"Sz", 0.}}});
    cases.push_back({"j1j2_mg_L6", spin_sectors(6), {{"Sz", 0.}}});
    {
        Case hubbard{"hubbard_chain_L4", {}, {}};
        for (int n = 0; n <= 8; ++n)
            for (int twice = -4; twice <= 4; ++twice) hubbard.sectors.push_back({{"N", double(n)}, {"Sz", twice / 2.}});
        cases.push_back(hubbard);
    }
    {
        Case spinless{"spinless_chain_L6", {}, {}};
        for (int n = 0; n <= 6; ++n) spinless.sectors.push_back({{"N", double(n)}});
        cases.push_back(spinless);
    }
    for (auto const& c : cases) {
        SCOPED_TRACE(c.name);
        double lowest = std::numeric_limits<double>::infinity();
        std::size_t states = 0;
        for (auto const& charges : c.sectors) {
            auto const problem = alps::ed::prepare_product(registry().at(c.name)(), sector(charges));
            states += problem.dimension();
            auto const result = problem.eigenstates(options(1, alps::ed::EigenstateMethod::dense));
            if (problem.dimension() == 0) { EXPECT_TRUE(result.eigenvalues.empty()); continue; }
            ASSERT_EQ(result.eigenvalues.size(), 1);
            lowest = std::min(lowest, result.eigenvalues[0]);
        }
        EXPECT_EQ(states, alps::ed::prepare_product(registry().at(c.name)()).dimension());
        EXPECT_NEAR(lowest, fixture_e0(c.name), 1e-8);
        if (!c.ground.empty()) {
            auto const result = alps::ed::prepare_product(registry().at(c.name)(), sector(c.ground))
                .eigenstates(options(1, alps::ed::EigenstateMethod::dense));
            EXPECT_NEAR(result.eigenvalues.at(0), fixture_e0(c.name), 1e-8);
        }
    }
}

TEST(ModelsFixtureE0, LanczosAgreesWithDenseInTheSingletSector) {
    auto const problem = alps::ed::prepare_product(mdl::heisenberg(lat::chain(12)), sector({{"Sz", 0.}}));
    ASSERT_EQ(problem.dimension(), 924);
    auto const dense = problem.eigenstates(options(4, alps::ed::EigenstateMethod::dense));
    auto const lanczos = problem.eigenstates(options(4, alps::ed::EigenstateMethod::lanczos));
    ASSERT_EQ(lanczos.eigenvalues.size(), 4);
    EXPECT_EQ(lanczos.method, alps::ed::EigenstateMethod::lanczos);
    for (std::size_t i = 0; i < 4; ++i) EXPECT_NEAR(lanczos.eigenvalues[i], dense.eigenvalues[i], 1e-8) << i;
    for (double residual : lanczos.residual_norms) EXPECT_LT(residual, 1e-7);
}

TEST(ModelsFixtureE0, HeisenbergChain16GroundStateByLanczos) {
    // L=16 periodic Heisenberg chain, Sz=0 sector (dimension 12870): the
    // automatic method selects Lanczos. The reference is the dense ground
    // state of the same sector, computed once (see the PR text); it agrees
    // with the Bethe-ansatz finite-size value.
    auto const problem = alps::ed::prepare_product(mdl::heisenberg(lat::chain(16)), sector({{"Sz", 0.}}));
    ASSERT_EQ(problem.dimension(), 12870);
    auto const result = problem.eigenstates(options(1, alps::ed::EigenstateMethod::automatic));
    EXPECT_EQ(result.method, alps::ed::EigenstateMethod::lanczos);
    ASSERT_EQ(result.eigenvalues.size(), 1);
    EXPECT_NEAR(result.eigenvalues[0], kHeisenberg16E0, 1e-8);
}
